<script setup lang="ts">
/**
 * Immediate on/off setting (`design/components/switch.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/switch.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/switch'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { agentMember, useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/switch.module.css'

export interface SwitchProps {
  ariaDescribedby?: string
  ariaLabel?: string
  /**
   * Names the switch from a label elsewhere on the page, such as `SettingsRow`'s row label,
   * which is one label for a whole row rather than one per control.
   */
  ariaLabelledby?: string
  ariaRequired?: boolean
  checked?: boolean
  defaultChecked?: boolean
  disabled?: boolean
  id?: string
  /**
   * Visible inline label. Omit it only when the context labels the switch, and then `aria-label`
   * is required.
   */
  label?: string
  name?: string
  value?: string
}

defineOptions({ name: 'Switch', inheritAttrs: false, controlKind: 'row-labelled' })

const props = withDefaults(defineProps<SwitchProps>(), {
  ariaRequired: undefined,
  checked: undefined,
  defaultChecked: undefined,
  disabled: false,
})
const emit = defineEmits<{ checkedChange: [checked: boolean] }>()
const uid = useId()
const track = useTemplateRef<HTMLElement>('track')
const documentDirection = useDirection(() => track.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    checked: props.checked,
    defaultChecked: props.defaultChecked,
    disabled: props.disabled,
    required: props.ariaRequired,
    name: props.name,
    value: props.value,
    onCheckedChange: (details) => {
      emit('checkedChange', details.checked)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const dataState = computed(() => (api.value.checked ? 'on' : 'off'))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Switch',
    element: () => track.value,
    state: () => ({ checked: api.value.checked, disabled: props.disabled }),
    actions: {
      check: () => api.value.setChecked(true),
      uncheck: () => api.value.setChecked(false),
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <button
    v-if="label === undefined"
    ref="track"
    :class="styles.track"
    type="button"
    role="switch"
    :id="id"
    :aria-checked="api.checked"
    :disabled="disabled"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-required="ariaRequired"
    :data-state="dataState"
    :data-disabled="disabled ? '' : undefined"
    :data-required="ariaRequired ? '' : undefined"
    data-member="switch"
    @click="api.toggleChecked()"
  >
    <!-- thumb -->
    <span :class="styles.thumb" :data-state="dataState" />
  </button>
  <label
    v-else
    :class="styles.row"
    :data-state="dataState"
    :data-disabled="disabled ? '' : undefined"
    :data-required="ariaRequired ? '' : undefined"
    data-member="switch"
  >
    <!-- track -->
    <button
      ref="track"
      :class="styles.track"
      type="button"
      role="switch"
      :id="id"
      :aria-checked="api.checked"
      :disabled="disabled"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="ariaDescribedby"
      :aria-required="ariaRequired"
      :data-state="dataState"
      :data-disabled="disabled ? '' : undefined"
      :data-required="ariaRequired ? '' : undefined"
      data-member="switch"
      @click="api.toggleChecked()"
    >
      <!-- thumb -->
      <span :class="styles.thumb" :data-state="dataState" />
    </button>
    <!-- label -->
    <span :class="styles.label">
      {{ label }}
    </span>
  </label>
  <input
    v-if="name !== undefined && api.checked"
    type="hidden"
    :name="name"
    :value="value ?? 'on'"
  />
</template>
